def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    edge_set = set(edges)

    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}

    for src, dst in edge_set:
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    if not items:
        return []
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current_sum + weight > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()

        if not line:
            continue
        if line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (missing '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')

    # Normalize CRLF and lone CR to LF
    text = text.replace('\r\n', '\n').replace('\r', '\n')

    lines = text.split('\n')

    results = []
    data_lines = []

    for line in lines:
        if line == '':
            # Blank line dispatches the pending event
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    return results
                results.append(data)
            data_lines = []
        elif line.startswith(':'):
            # Comment – ignore
            pass
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            # Other field (event, id, retry, etc.) – ignore
            pass

    # Unterminated final event is ignored
    return results

def fifo_admit(active, queued, budget, slots):
    for token in queued:
        if token > budget:
            raise ValueError(f"queued reservation {token} exceeds budget {budget}")

    rem_budget = budget - sum(active)
    rem_slots = slots - len(active)

    admitted = []
    for token in queued:
        if token <= rem_budget and rem_slots > 0:
            admitted.append(token)
            rem_budget -= token
            rem_slots -= 1
        else:
            break

    remaining = queued[len(admitted):]
    return (admitted, remaining)
